-- Seed 100 bilingual, unscheduled daily verses for deterministic rotation.
-- English source: World English Bible Classic (public domain), eBible.org.
-- Tamil source: Tamil Bible 1957 digitization (public domain in India), TFBF/berinaniesh.
-- Existing manually entered verses are preserved; matching English references are not duplicated.

begin;

with seed (
  id, verse_en, verse_ta, reference_en, reference_ta,
  translation_en, translation_ta, scheduled_date, active, status, display_order
) as (
values
  ('b1000000-0000-4000-8000-000000000001', 'In the beginning, God created the heavens and the earth.', 'ஆதியிலே தேவன் வானத்தையும் பூமியையும் சிருஷ்டித்தார்.', 'Genesis 1:1', 'ஆதியாகமம் 1:1', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 0),
  ('b1000000-0000-4000-8000-000000000002', 'God created man in his own image. In God’s image he created him; male and female he created them.', 'தேவன் தம்முடைய சாயலாக மனுஷனைச் சிருஷ்டித்தார், அவனைத் தேவசாயலாகவே சிருஷ்டித்தார்; ஆணும் பெண்ணுமாக அவர்களைச் சிருஷ்டித்தார்.', 'Genesis 1:27', 'ஆதியாகமம் 1:27', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 1),
  ('b1000000-0000-4000-8000-000000000003', 'I will make of you a great nation. I will bless you and make your name great. You will be a blessing.', 'நான் உன்னைப் பெரிய ஜாதியாக்கி, உன்னை ஆசீர்வதித்து, உன் பேரைப் பெருமைப்படுத்துவேன்; நீ ஆசீர்வாதமாய் இருப்பாய்.', 'Genesis 12:2', 'ஆதியாகமம் 12:2', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 2),
  ('b1000000-0000-4000-8000-000000000004', 'Behold, I am with you, and will keep you, wherever you go, and will bring you again into this land. For I will not leave you until I have done that which I have spoken of to you.”', 'நான் உன்னோடே இருந்து, நீ போகிற இடத்திலெல்லாம் உன்னைக் காத்து, இந்தத் தேசத்துக்கு உன்னைத்திரும்பி வரப்பண்ணுவேன்; நான் உனக்குச் சொன்னதைச் செய்யுமளவும் உன்னைக் கைவிடுவதில்லை என்றார்.', 'Genesis 28:15', 'ஆதியாகமம் 28:15', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 3),
  ('b1000000-0000-4000-8000-000000000005', 'As for you, you meant evil against me, but God meant it for good, to save many people alive, as is happening today.', 'நீங்கள் எனக்குத் தீமைசெய்ய நினைத்தீர்கள்; தேவனோ, இப்பொழுது நடந்துவருகிறபடியே, வெகு ஜனங்களை உயிரோடே காக்கும்படிக்கு, அதை நன்மையாக முடியப்பண்ணினார்.', 'Genesis 50:20', 'ஆதியாகமம் 50:20', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 4),
  ('b1000000-0000-4000-8000-000000000006', 'Yahweh will fight for you, and you shall be still.”', 'கர்த்தர் உங்களுக்காக யுத்தம்பண்ணுவார்; நீங்கள் சும்மாயிருப்பீர்கள் என்றான்.', 'Exodus 14:14', 'யாத்திராகமம் 14:14', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 5),
  ('b1000000-0000-4000-8000-000000000007', 'Yah is my strength and song. He has become my salvation. This is my God, and I will praise him; my father’s God, and I will exalt him.', 'கர்த்தர் என் பெலனும் என் கீதமுமானவர்; அவர் எனக்கு இரட்சிப்புமானவர்; அவரே என் தேவன், அவருக்கு வாசஸ்தலத்தை ஆயத்தம்பண்ணுவேன்; அவரே என் தகப்பனுடைய தேவன், அவரை உயர்த்துவேன்;', 'Exodus 15:2', 'யாத்திராகமம் 15:2', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 6),
  ('b1000000-0000-4000-8000-000000000008', '“Honor your father and your mother, that your days may be long in the land which Yahweh your God gives you.', 'உன் தேவனாகிய கர்த்தர் உனக்குக் கொடுக்கிற தேசத்திலே உன் நாட்கள் நீடித்திருப்பதற்கு, உன் தகப்பனையும் உன் தாயையும் கனம்பண்ணுவாயாக.', 'Exodus 20:12', 'யாத்திராகமம் 20:12', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 7),
  ('b1000000-0000-4000-8000-000000000009', 'He said, “My presence will go with you, and I will give you rest.”', 'அதற்கு அவர்: என் சமுகம் உனக்கு முன்பாகச் செல்லும், நான் உனக்கு இளைப்பாறுதல் தருவேன் என்றார்.', 'Exodus 33:14', 'யாத்திராகமம் 33:14', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 8),
  ('b1000000-0000-4000-8000-000000000010', 'You shall love Yahweh your God with all your heart, with all your soul, and with all your might.', 'நீ உன் தேவனாகிய கர்த்தரிடத்தில் உன் முழு இருதயத்தோடும், உன் முழு ஆத்துமாவோடும், உன் முழுப் பலத்தோடும் அன்புக்கூருவாயாக.', 'Deuteronomy 6:5', 'உபாகமம் 6:5', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 9),
  ('b1000000-0000-4000-8000-000000000011', 'Know therefore that Yahweh your God himself is God, the faithful God, who keeps covenant and loving kindness to a thousand generations with those who love him and keep his commandments,', 'ஆகையால் உன் தேவனாகிய கர்த்தரே தேவன் என்றும், தம்மில் அன்புகூர்ந்து, தமது கற்பனைகளைக் கைக்கொள்ளுகிறவர்களுக்கு அவர் ஆயிரம் தலைமுறைமட்டும் உடன்படிக்கையையும் தயவையும் காக்கிற உண்மையுள்ள தேவன் என்றும்,', 'Deuteronomy 7:9', 'உபாகமம் 7:9', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 10),
  ('b1000000-0000-4000-8000-000000000012', 'Yahweh himself is who goes before you. He will be with you. He will not fail you nor forsake you. Don’t be afraid. Don’t be discouraged.”', 'கர்த்தர்தாமே உனக்கு முன்பாகப் போகிறவர், அவர் உன்னோடே இருப்பார்; அவர் உன்னை விட்டு விலகுவதுமில்லை, உன்னைக் கைவிடுவதுமில்லை; நீ பயப்படவும் கலங்கவும் வேண்டாம் என்றான்.', 'Deuteronomy 31:8', 'உபாகமம் 31:8', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 11),
  ('b1000000-0000-4000-8000-000000000013', 'This book of the law shall not depart from your mouth, but you shall meditate on it day and night, that you may observe to do according to all that is written in it; for then you shall make your way prosperous, and then you shall have good success.', 'இந்த நியாயப்பிரமாண புஸ்தகம் உன் வாயைவிட்டுப் பிரியாதிருப்பதாக; இதில் எழுதியிருக்கிறவைகளின்படியெல்லாம் நீ செய்யக் கவனமாயிருக்கும்படி, இரவும் பகலும் அதைத் தியானித்துக்கொண்டிருப்பாயாக; அப்பொழுது நீ உன் வழியை வாய்க்கப்பண்ணுவாய், அப்பொழுது புத்திமானாயும் நடந்துகொள்ளுவாய்.', 'Joshua 1:8', 'யோசுவா 1:8', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 12),
  ('b1000000-0000-4000-8000-000000000014', 'Haven’t I commanded you? Be strong and courageous. Don’t be afraid. Don’t be dismayed, for Yahweh your God is with you wherever you go.”', 'நான் உனக்குக் கட்டளையிடவில்லையா? பலங்கொண்டு திடமனதாயிரு; திகையாதே, கலங்காதே, நீ போகும் இடமெல்லாம் உன் தேவனாகிய கர்த்தர் உன்னோடே இருக்கிறார் என்றார்.', 'Joshua 1:9', 'யோசுவா 1:9', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 13),
  ('b1000000-0000-4000-8000-000000000015', 'If it seems evil to you to serve Yahweh, choose today whom you will serve; whether the gods which your fathers served that were beyond the River, or the gods of the Amorites, in whose land you dwell; but as for me and my house, we will serve Yahweh.”', 'கர்த்தரைச் சேவிக்கிறது உங்கள் பார்வைக்கு ஆகாததாய்க் கண்டால், பின்னை யாரைச் சேவிப்பீர்கள் என்று இன்று தெரிந்துகொள்ளுங்கள்; நதிக்கு அப்புறத்தில் உங்கள் பிதாக்கள் சேவித்த தேவர்களைச் சேவிப்பீர்களோ? நீங்கள் வாசம்பண்ணுகிற தேசத்துக் குடிகளாகிய எமோரியரின் தேவர்களைச் சேவிப்பீர்களோ? நானும் என் வீட்டாருமோவென்றால், கர்த்தரையே சேவிப்போம் என்றான்.', 'Joshua 24:15', 'யோசுவா 24:15', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 14),
  ('b1000000-0000-4000-8000-000000000016', 'But Yahweh said to Samuel, “Don’t look on his face, or on the height of his stature, because I have rejected him; for I don’t see as man sees. For man looks at the outward appearance, but Yahweh looks at the heart.”', 'கர்த்தர் சாமுவேலை நோக்கி: நீ இவனுடைய முகத்தையும், இவனுடைய சரீரவளர்ச்சியையும் பார்க்கவேண்டாம்; நான் இவனைப் புறக்கணித்தேன்; மனுஷன் பார்க்கிறபடி நான் பாரேன்; மனுஷன் முகத்தைப் பார்ப்பான்; கர்த்தரோ இருதயத்தைப் பார்க்கிறார் என்றார்.', '1 Samuel 16:7', '1 சாமுவேல் 16:7', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 15),
  ('b1000000-0000-4000-8000-000000000017', 'As for God, his way is perfect. Yahweh’s word is tested. He is a shield to all those who take refuge in him.', 'தேவனுடைய வழி உத்தமமானது; கர்த்தருடைய வசனம் புடமிடப்பட்டது; தம்மை நம்புகிற அனைவருக்கும் அவர் கேடகமாயிருக்கிறார்.', '2 Samuel 22:31', '2 சாமுவேல் 22:31', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 16),
  ('b1000000-0000-4000-8000-000000000018', 'Seek Yahweh and his strength. Seek his face forever more.', 'கர்த்தரையும் அவர் வல்லமையையும் நாடுங்கள்; அவர் சமுகத்தை நித்தமும் தேடுங்கள்.', '1 Chronicles 16:11', '1 நாளாகமம் 16:11', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 17),
  ('b1000000-0000-4000-8000-000000000019', 'if my people who are called by my name will humble themselves, pray, seek my face, and turn from their wicked ways, then I will hear from heaven, will forgive their sin, and will heal their land.', 'என் நாமம் தரிக்கப்பட்ட என் ஜனங்கள் தங்களைத் தாழ்த்தி, ஜெபம்பண்ணி, என் முகத்தைத் தேடி, தங்கள் பொல்லாத வழிகளைவிட்டுத் திரும்பினால், அப்பொழுது பரலோகத்திலிருக்கிற நான் கேட்டு, அவர்கள் பாவத்தை மன்னித்து, அவர்கள் தேசத்துக்கு க்ஷேமத்தைக் கொடுப்பேன்.', '2 Chronicles 7:14', '2 நாளாகமம் 7:14', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 18),
  ('b1000000-0000-4000-8000-000000000020', 'Then he said to them, “Go your way. Eat the fat, drink the sweet, and send portions to him for whom nothing is prepared, for today is holy to our Lord. Don’t be grieved, for the joy of Yahweh is your strength.”', 'பின்னும் அவன் அவர்களை நோக்கி: நீங்கள் போய்க் கொழுமையானதைப் புசித்து, மதுரமானதைக் குடித்து, ஒன்றுமில்லாதவர்களுக்குப் பங்குகளை அனுப்புங்கள்; இந்த நாள் நம்முடைய ஆண்டவருக்குப் பரிசுத்தமான நாள், விசாரப்படவேண்டாம்; கர்த்தருக்குள் மகிழ்ச்சியாயிருப்பதே உங்களுடைய பெலன் என்றான்.', 'Nehemiah 8:10', 'நெகேமியா 8:10', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 19),
  ('b1000000-0000-4000-8000-000000000021', 'But as for me, I know that my Redeemer lives. In the end, he will stand upon the earth.', 'என் மீட்பர் உயிரோடிருக்கிறார் என்றும், அவர் கடைசி நாளில் பூமியின்மேல் நிற்பார் என்றும் நான் அறிந்திருக்கிறேன்.', 'Job 19:25', 'யோபு 19:25', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 20),
  ('b1000000-0000-4000-8000-000000000022', '“I know that you can do all things, and that no purpose of yours can be restrained.', 'தேவரீர் சகலத்தையும் செய்ய வல்லவர்; நீர் செய்ய நினைத்தது தடைபடாது என்பதை அறிந்திருக்கிறேன்.', 'Job 42:2', 'யோபு 42:2', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 21),
  ('b1000000-0000-4000-8000-000000000023', 'Yahweh is my shepherd; I shall lack nothing.', 'கர்த்தர் என் மேய்ப்பராயிருக்கிறார்; நான் தாழ்ச்சியடையேன்.', 'Psalm 23:1', 'சங்கீதம் 23:1', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 22),
  ('b1000000-0000-4000-8000-000000000024', 'Yahweh is my light and my salvation. Whom shall I fear? Yahweh is the strength of my life. Of whom shall I be afraid?', 'கர்த்தர் என் வெளிச்சமும் என் இரட்சிப்புமானவர், யாருக்குப் பயப்படுவேன்? கர்த்தர் என் ஜீவனின் அரணானவர், யாருக்கு அஞ்சுவேன்?', 'Psalm 27:1', 'சங்கீதம் 27:1', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 23),
  ('b1000000-0000-4000-8000-000000000025', 'Oh taste and see that Yahweh is good. Blessed is the man who takes refuge in him.', 'கர்த்தர் நல்லவர் என்பதை ருசித்துப்பாருங்கள்; அவர்மேல் நம்பிக்கையாயிருக்கிற மனுஷன் பாக்கியவான்.', 'Psalm 34:8', 'சங்கீதம் 34:8', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 24),
  ('b1000000-0000-4000-8000-000000000026', 'Also delight yourself in Yahweh, and he will give you the desires of your heart.', 'கர்த்தரிடத்தில் மனமகிழ்ச்சியாயிரு; அவர் உன் இருதயத்தின் வேண்டுதல்களை உனக்கு அருள்செய்வார்.', 'Psalm 37:4', 'சங்கீதம் 37:4', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 25),
  ('b1000000-0000-4000-8000-000000000027', 'God is our refuge and strength, a very present help in trouble.', 'தேவன் நமக்கு அடைக்கலமும் பெலனும், ஆபத்துக்காலத்தில் அனுகூலமான துணையுமானவர்.', 'Psalm 46:1', 'சங்கீதம் 46:1', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 26),
  ('b1000000-0000-4000-8000-000000000028', 'Create in me a clean heart, O God. Renew a right spirit within me.', 'தேவனே, சுத்த இருதயத்தை என்னிலே சிருஷ்டியும், நிலைவரமான ஆவியை என் உள்ளத்திலே புதுப்பியும்.', 'Psalm 51:10', 'சங்கீதம் 51:10', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 27),
  ('b1000000-0000-4000-8000-000000000029', 'Cast your burden on Yahweh and he will sustain you. He will never allow the righteous to be moved.', 'கர்த்தர்மேல் உன் பாரத்தை வைத்துவிடு, அவர் உன்னை ஆதரிப்பார்; நீதிமானை ஒருபோதும் தள்ளாடவொட்டார்.', 'Psalm 55:22', 'சங்கீதம் 55:22', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 28),
  ('b1000000-0000-4000-8000-000000000030', 'When I am afraid, I will put my trust in you.', 'நான் பயப்படுகிற நாளில் உம்மை நம்புவேன்.', 'Psalm 56:3', 'சங்கீதம் 56:3', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 29),
  ('b1000000-0000-4000-8000-000000000031', 'He who dwells in the secret place of the Most High will rest in the shadow of the Almighty.', 'உன்னதமானவரின் மறைவிலிருக்கிறவன் சர்வவல்லவருடைய நிழலில் தங்குவான்.', 'Psalm 91:1', 'சங்கீதம் 91:1', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 30),
  ('b1000000-0000-4000-8000-000000000032', 'As far as the east is from the west, so far has he removed our transgressions from us.', 'மேற்குக்கும் கிழக்குக்கும் எவ்வளவு தூரமோ, அவ்வளவு தூரமாய் அவர் நம்முடைய பாவங்களை நம்மைவிட்டு விலக்கினார்.', 'Psalm 103:12', 'சங்கீதம் 103:12', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 31),
  ('b1000000-0000-4000-8000-000000000033', 'This is the day that Yahweh has made. We will rejoice and be glad in it!', 'இது கர்த்தர் உண்டுபண்ணின நாள்; இதிலே களிகூர்ந்து மகிழக்கடவோம்.', 'Psalm 118:24', 'சங்கீதம் 118:24', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 32),
  ('b1000000-0000-4000-8000-000000000034', 'I have hidden your word in my heart, that I might not sin against you.', 'நான் உமக்கு விரோதமாய்ப் பாவஞ்செய்யாதபடிக்கு, உமது வாக்கை என்னிருதயத்தில் வைத்து வைத்தேன்.', 'Psalm 119:11', 'சங்கீதம் 119:11', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 33),
  ('b1000000-0000-4000-8000-000000000035', 'Your word is a lamp to my feet, and a light for my path.', 'உம்முடைய வசனம் என் கால்களுக்குத் தீபமும், என் பாதைக்கு வெளிச்சமுமாயிருக்கிறது.', 'Psalm 119:105', 'சங்கீதம் 119:105', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 34),
  ('b1000000-0000-4000-8000-000000000036', 'I will lift up my eyes to the hills. Where does my help come from?', 'எனக்கு ஒத்தாசை வரும் பர்வதங்களுக்கு நேராக என் கண்களை ஏறெடுக்கிறேன்.', 'Psalm 121:1', 'சங்கீதம் 121:1', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 35),
  ('b1000000-0000-4000-8000-000000000037', 'I will give thanks to you, for I am fearfully and wonderfully made. Your works are wonderful. My soul knows that very well.', 'நான் பிரமிக்கத்தக்க அதிசயமாய் உண்டாக்கப்பட்டபடியால், உம்மைத் துதிப்பேன்; உமது கிரியைகள் அதிசயமானவைகள்; அது என் ஆத்துமாவுக்கு நன்றாய்த் தெரியும்.', 'Psalm 139:14', 'சங்கீதம் 139:14', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 36),
  ('b1000000-0000-4000-8000-000000000038', 'He heals the broken in heart, and binds up their wounds.', 'இருதயம் நொறுங்குண்டவர்களைக் குணமாக்குகிறார், அவர்களுடைய காயங்களைக் கட்டுகிறார்.', 'Psalm 147:3', 'சங்கீதம் 147:3', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 37),
  ('b1000000-0000-4000-8000-000000000039', 'Trust in Yahweh with all your heart, and don’t lean on your own understanding.', 'உன் சுயபுத்தியின்மேல் சாயாமல், உன் முழு இருதயத்தோடும் கர்த்தரில் நம்பிக்கையாயிருந்து,', 'Proverbs 3:5', 'நீதிமொழிகள் 3:5', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 38),
  ('b1000000-0000-4000-8000-000000000040', 'In all your ways acknowledge him, and he will make your paths straight.', 'உன் வழிகளிலெல்லாம் அவரை நினைத்துக்கொள்; அப்பொழுது அவர் உன் பாதைகளைச் செவ்வைப்படுத்துவார்.', 'Proverbs 3:6', 'நீதிமொழிகள் 3:6', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 39),
  ('b1000000-0000-4000-8000-000000000041', 'Keep your heart with all diligence, for out of it is the wellspring of life.', 'எல்லாக் காவலோடும் உன் இருதயத்தைக் காத்துக்கொள், அதினிடத்தினின்று ஜீவவூற்று புறப்படும்.', 'Proverbs 4:23', 'நீதிமொழிகள் 4:23', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 40),
  ('b1000000-0000-4000-8000-000000000042', 'Commit your deeds to Yahweh, and your plans shall succeed.', 'உன் செய்கைகளைக் கர்த்தருக்கு ஒப்புவி; அப்பொழுது உன் யோசனைகள் உறுதிப்படும்.', 'Proverbs 16:3', 'நீதிமொழிகள் 16:3', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 41),
  ('b1000000-0000-4000-8000-000000000043', 'A friend loves at all times; and a brother is born for adversity.', 'சிநேகிதன் எல்லாக் காலத்திலும் சிநேகிப்பான்; இடுக்கணில் உதவவே சகோதரன் பிறந்திருக்கிறான்.', 'Proverbs 17:17', 'நீதிமொழிகள் 17:17', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 42),
  ('b1000000-0000-4000-8000-000000000044', 'Yahweh’s name is a strong tower: the righteous run to him, and are safe.', 'கர்த்தரின் நாமம் பலத்த துருகம்; நீதிமான் அதற்குள் ஓடிச் சுகமாயிருப்பான்.', 'Proverbs 18:10', 'நீதிமொழிகள் 18:10', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 43),
  ('b1000000-0000-4000-8000-000000000045', 'Train up a child in the way he should go, and when he is old he will not depart from it.', 'பிள்ளையானவன் நடக்கவேண்டிய வழியிலே அவனை நடத்து; அவன் முதிர்வயதிலும் அதை விடாதிருப்பான்.', 'Proverbs 22:6', 'நீதிமொழிகள் 22:6', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 44),
  ('b1000000-0000-4000-8000-000000000046', 'Iron sharpens iron; so a man sharpens his friend’s countenance.', 'இரும்பை இரும்பு கருக்கிடும்; அப்படியே மனுஷனும் தன் சிநேதிதனுடைய முகத்தைக் கருக்கிடுகிறான்.', 'Proverbs 27:17', 'நீதிமொழிகள் 27:17', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 45),
  ('b1000000-0000-4000-8000-000000000047', 'For everything there is a season, and a time for every purpose under heaven:', 'ஒவ்வொன்றிற்கும் ஒவ்வொரு காலமுண்டு; வானத்தின் கீழிருக்கிற ஒவ்வொரு காரியத்துக்கும் ஒவ்வொரு சமயமுண்டு.', 'Ecclesiastes 3:1', 'பிரசங்கி 3:1', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 46),
  ('b1000000-0000-4000-8000-000000000048', 'You will keep whoever’s mind is steadfast in perfect peace, because he trusts in you.', 'உம்மை உறுதியாய்ப் பற்றிக்கொண்ட மனதையுடையவன் உம்மையே நம்பியிருக்கிறபடியால், நீர் அவனைப் பூரண சமாதானத்துடன் காத்துக்கொள்வீர்.', 'Isaiah 26:3', 'ஏசாயா 26:3', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 47),
  ('b1000000-0000-4000-8000-000000000049', 'but those who wait for Yahweh will renew their strength. They will mount up with wings like eagles. They will run, and not be weary. They will walk, and not faint.', 'கர்த்தருக்குக் காத்திருக்கிறவர்களோ புதுப்பெலன் அடைந்து, கழுகுகளைப்போலச் செட்டைகளை அடித்து எழும்புவார்கள்; அவர்கள் ஓடினாலும் இளைப்படையார்கள், நடந்தாலும் சோர்ந்துபோகார்கள்.', 'Isaiah 40:31', 'ஏசாயா 40:31', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 48),
  ('b1000000-0000-4000-8000-000000000050', 'Don’t you be afraid, for I am with you. Don’t be dismayed, for I am your God. I will strengthen you. Yes, I will help you. Yes, I will uphold you with the right hand of my righteousness.', 'நீ பயப்படாதே, நான் உன்னுடனே இருக்கிறேன்; திகையாதே, நான் உன் தேவன்; நான் உன்னைப் பலப்படுத்தி உனக்குச் சகாயம்பண்ணுவேன்; என் நீதியின் வலதுகரத்தினால் உன்னைத் தாங்குவேன்.', 'Isaiah 41:10', 'ஏசாயா 41:10', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 49),
  ('b1000000-0000-4000-8000-000000000051', '“ You are the light of the world. A city located on a hill can’ t be hidden.', 'நீங்கள் உலகத்துக்கு வெளிச்சமாயிருக்கிறீர்கள்; மலையின்மேல் இருக்கிற பட்டணம் மறைந்திருக்கமாட்டாது.', 'Matthew 5:14', 'மத்தேயு 5:14', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 50),
  ('b1000000-0000-4000-8000-000000000052', 'Even so, let your light shine before men, that they may see your good works and glorify your Father who is in heaven.', 'இவ்விதமாய், மனுஷர் உங்கள் நற்கிரியைகளைக் கண்டு, பரலோகத்திலிருக்கிற உங்கள் பிதாவை மகிமைப்படுத்தும்படி, உங்கள் வெளிச்சம் அவர்கள் முன்பாகப் பிரகாசிக்கக்கடவது.', 'Matthew 5:16', 'மத்தேயு 5:16', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 51),
  ('b1000000-0000-4000-8000-000000000053', 'But seek first God’s Kingdom and his righteousness; and all these things will be given to you as well.', 'முதலாவது தேவனுடைய ராஜ்யத்தையும் அவருடைய நீதியையும் தேடுங்கள், அப்பொழுது இவைகளெல்லாம் உங்களுக்குக்கூடக் கொடுக்கப்படும்.', 'Matthew 6:33', 'மத்தேயு 6:33', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 52),
  ('b1000000-0000-4000-8000-000000000054', '“Ask, and it will be given you. Seek, and you will find. Knock, and it will be opened for you.', 'கேளுங்கள், அப்பொழுது உங்களுக்குக் கொடுக்கப்படும்; தேடுங்கள், அப்பொழுது கண்டடைவீர்கள்; தட்டுங்கள், அப்பொழுது உங்களுக்குத் திறக்கப்படும்;', 'Matthew 7:7', 'மத்தேயு 7:7', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 53),
  ('b1000000-0000-4000-8000-000000000055', '“ Come to me, all you who labor and are heavily burdened, and I will give you rest.', 'வருத்தப்பட்டுப் பாரஞ்சுமக்கிறவர்களே! நீங்கள் எல்லாரும் என்னிடத்தில் வாருங்கள்; நான் உங்களுக்கு இளைப்பாறுதல் தருவேன்.', 'Matthew 11:28', 'மத்தேயு 11:28', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 54),
  ('b1000000-0000-4000-8000-000000000056', 'Looking at them, Jesus said, “ With men this is impossible, but with God all things are possible.”', 'இயேசு, அவர்களைப் பார்த்து: மனுஷரால் இது கூடாததுதான்; தேவனாலே எல்லாம் கூடும் என்றார்.', 'Matthew 19:26', 'மத்தேயு 19:26', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 55),
  ('b1000000-0000-4000-8000-000000000057', 'Jesus said to him, “‘ You shall love the Lord your God with all your heart, with all your soul, and with all your mind.’', 'இயேசு அவனை நோக்கி: உன் தேவனாகிய கர்த்தரிடத்தில் உன் முழு இருதயத்தோடும் உன் முழு ஆத்துமாவோடும் உன் முழு மனதோடும் அன்புகூருவாயாக;', 'Matthew 22:37', 'மத்தேயு 22:37', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 56),
  ('b1000000-0000-4000-8000-000000000058', 'Go and make disciples of all nations, baptizing them in the name of the Father and of the Son and of the Holy Spirit,', 'ஆகையால், நீங்கள் புறப்பட்டுப்போய், சகல ஜாதிகளையும் சீஷராக்கி, பிதா குமாரன் பரிசுத்த ஆவியின் நாமத்திலே அவர்களுக்கு ஞானஸ்நானங்கொடுத்து,', 'Matthew 28:19', 'மத்தேயு 28:19', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 57),
  ('b1000000-0000-4000-8000-000000000059', 'Jesus, looking at them, said, “ With men it is impossible, but not with God, for all things are possible with God.”', 'இயேசு அவர்களைப் பார்த்து: மனுஷரால் இது கூடாததுதான், தேவனால் இது கூடாததல்ல; தேவனாலே எல்லாம் கூடும் என்றார்.', 'Mark 10:27', 'மாற்கு 10:27', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 58),
  ('b1000000-0000-4000-8000-000000000060', 'You shall love the Lord your God with all your heart, with all your soul, with all your mind, and with all your strength.’ This is the first commandment.', 'உன் தேவனாகிய கர்த்தரிடத்தில் உன் முழு இருதயத்தோடும், உன் முழு ஆத்துமாவோடும், உன் முழு மனதோடும், உன் முழுப் பலத்தோடும் அன்புகூருவாயாக என்பதே பிரதான கற்பனை.', 'Mark 12:30', 'மாற்கு 12:30', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 59),
  ('b1000000-0000-4000-8000-000000000061', 'For nothing spoken by God is impossible.”', 'தேவனாலே கூடாதகாரியம் ஒன்றுமில்லை என்றான்.', 'Luke 1:37', 'லூக்கா 1:37', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 60),
  ('b1000000-0000-4000-8000-000000000062', '“ As you would like people to do to you, do exactly so to them.', 'மனுஷர் உங்களுக்கு எப்படிச் செய்யவேண்டுமென்று விரும்புகிறீர்களோ, அப்படியே நீங்களும் அவர்களுக்குச் செய்யுங்கள்.', 'Luke 6:31', 'லூக்கா 6:31', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 61),
  ('b1000000-0000-4000-8000-000000000063', 'But he said, “ On the contrary, blessed are those who hear the word of God, and keep it.”', 'அதற்கு அவர்: அப்படியானாலும், தேவனுடைய வார்த்தையைக் கேட்டு, அதைக் காத்துக்கொள்ளுகிறவர்களே அதிக பாக்கியவான்கள் என்றார்.', 'Luke 11:28', 'லூக்கா 11:28', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 62),
  ('b1000000-0000-4000-8000-000000000064', 'But he said, “ The things which are impossible with men are possible with God.”', 'அதற்கு அவர்: மனுஷரால் கூடாதவைகள் தேவனால் கூடும் என்றார்.', 'Luke 18:27', 'லூக்கா 18:27', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 63),
  ('b1000000-0000-4000-8000-000000000065', 'In the beginning was the Word, and the Word was with God, and the Word was God.', 'ஆதியிலே வார்த்தை இருந்தது, அந்த வார்த்தை தேவனிடத்திலிருந்தது, அந்த வார்த்தை தேவனாயிருந்தது.', 'John 1:1', 'யோவான் 1:1', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 64),
  ('b1000000-0000-4000-8000-000000000066', 'For God so loved the world, that he gave his only born Son, that whoever believes in him should not perish, but have eternal life.', 'தேவன், தம்முடைய ஒரேபேறான குமாரனை விசுவாசிக்கிறவன் எவனோ அவன் கெட்டுப்போகாமல் நித்தியஜீவனை அடையும்படிக்கு, அவரைத் தந்தருளி, இவ்வளவாய் உலகத்தில் அன்பு கூர்ந்தார்.', 'John 3:16', 'யோவான் 3:16', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 65),
  ('b1000000-0000-4000-8000-000000000067', 'Again, therefore, Jesus spoke to them, saying, “ I am the light of the world. He who follows me will not walk in the darkness, but will have the light of life.”', 'மறுபடியும் இயேசு ஜனங்களை நோக்கி: நான் உலகத்திற்கு ஒளியாயிருக்கிறேன், என்னைப் பின்பற்றுகிறவன் இருளிலே நடவாமல் ஜீவஒளியை அடைந்திருப்பான் என்றார்.', 'John 8:12', 'யோவான் 8:12', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 66),
  ('b1000000-0000-4000-8000-000000000068', 'The thief only comes to steal, kill, and destroy. I came that they may have life, and may have it abundantly.', 'திருடன் திருடவும் கொல்லவும் அழிக்கவும் வருகிறானேயன்றி வேறொன்றுக்கும் வரான். நானோ அவைகளுக்கு ஜீவன் உண்டாயிருக்கவும், அது பரிபூரணப்படவும் வந்தேன்.', 'John 10:10', 'யோவான் 10:10', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 67),
  ('b1000000-0000-4000-8000-000000000069', 'Jesus said to her, “ I am the resurrection and the life. He who believes in me will still live, even if he dies.', 'இயேசு அவளை நோக்கி: நானே உயிர்த்தெழுதலும் ஜீவனுமாயிருக்கிறேன், என்னை விசுவாசிக்கிறவன் மரித்தாலும் பிழைப்பான்;', 'John 11:25', 'யோவான் 11:25', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 68),
  ('b1000000-0000-4000-8000-000000000070', 'A new commandment I give to you, that you love one another. Just as I have loved you, you also love one another.', 'நீங்கள் ஒருவரிலொருவர் அன்பாயிருங்கள்; நான் உங்களில் அன்பாயிருந்ததுபோல நீங்களும் ஒருவரிலொருவர் அன்பாயிருங்கள் என்கிற புதிதான கட்டளையை உங்களுக்குக் கொடுக்கிறேன்.', 'John 13:34', 'யோவான் 13:34', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 69),
  ('b1000000-0000-4000-8000-000000000071', 'Jesus said to him, “ I am the way, the truth, and the life. No one comes to the Father, except through me.', 'அதற்கு இயேசு: நானே வழியும் சத்தியமும் ஜீவனுமாயிருக்கிறேன்; என்னாலேயல்லாமல் ஒருவனும் பிதாவினிடத்தில் வரான்.', 'John 14:6', 'யோவான் 14:6', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 70),
  ('b1000000-0000-4000-8000-000000000072', 'Peace I leave with you. My peace I give to you; not as the world gives, I give to you. Don’ t let your heart be troubled, neither let it be fearful.', 'சமாதானத்தை உங்களுக்கு வைத்துப்போகிறேன், என்னுடைய சாமாதானத்தையே உங்களுக்குக் கொடுக்கிறேன்; உலகம் கொடுக்கிறபிரகாரம் நான் உங்களுக்குக் கொடுக்கிறதில்லை. உங்கள் இருதயம் கலங்காமலும் பயப்படாமலும் இருப்பதாக.', 'John 14:27', 'யோவான் 14:27', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 71),
  ('b1000000-0000-4000-8000-000000000073', 'I am the vine. You are the branches. He who remains in me and I in him bears much fruit, for apart from me you can do nothing.', 'நானே திராட்சச்செடி, நீங்கள் கொடிகள். ஒருவன் என்னிலும் நான் அவனிலும் நிலைத்திருந்தால், அவன் மிகுந்த கனிகளைக் கொடுப்பான்; என்னையல்லாமல் உங்களால் ஒன்றும் செய்யக்கூடாது.', 'John 15:5', 'யோவான் 15:5', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 72),
  ('b1000000-0000-4000-8000-000000000074', 'Greater love has no one than this, that someone lay down his life for his friends.', 'ஒருவன் தன் சிநேகிதருக்காகத் தன் ஜீவனைக் கொடுக்கிற அன்பிலும் அதிகமான அன்பு ஒருவரிடத்திலுமில்லை.', 'John 15:13', 'யோவான் 15:13', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 73),
  ('b1000000-0000-4000-8000-000000000075', 'I have told you these things, that in me you may have peace. In the world you have trouble; but cheer up! I have overcome the world.”', 'என்னிடத்தில் உங்களுக்குச் சமாதானம் உண்டாயிருக்கும்பொருட்டு இவைகளை உங்களுக்குச் சொன்னேன். உலகத்தில் உங்களுக்கு உபத்திரவம் உண்டு, ஆனாலும் திடன்கொள்ளுங்கள்; நான் உலகத்தை ஜெயித்தேன் என்றார்.', 'John 16:33', 'யோவான் 16:33', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 74),
  ('b1000000-0000-4000-8000-000000000076', 'But you will receive power when the Holy Spirit has come upon you. You will be witnesses to me in Jerusalem, in all Judea and Samaria, and to the uttermost parts of the earth.”', 'பரிசுத்த ஆவி உங்களிடத்தில் வரும்போது நீங்கள் பெலனடைந்து, எருசலேமிலும், யூதேயா முழுவதிலும், சமாரியாவிலும், பூமியின் கடைசிப்பரியந்தமும், எனக்குச் சாட்சிகளாயிருப்பீர்கள் என்றார்.', 'Acts 1:8', 'அப்போஸ்தலர் 1:8', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 75),
  ('b1000000-0000-4000-8000-000000000077', 'There is salvation in no one else, for there is no other name under heaven that is given among men, by which we must be saved!”', 'அவராலேயன்றி வேறொருவராலும் இரட்சிப்பு இல்லை; நாம் இரட்சிக்கப்படும்படிக்கு வானத்தின் கீழெங்கும், மனுஷர்களுக்குள்ளே அவருடைய நாமமேயல்லாமல் வேறொரு நாமம் கட்டளையிடப்படவும் இல்லை என்றான்.', 'Acts 4:12', 'அப்போஸ்தலர் 4:12', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 76),
  ('b1000000-0000-4000-8000-000000000078', 'They said, “Believe in the Lord Jesus Christ, and you will be saved, you and your household.”', 'அதற்கு அவர்கள்: கர்த்தராகிய இயேசுகிறிஸ்துவை விசுவாசி, அப்பொழுது நீயும் உன் வீட்டாரும் இரட்சிக்கப்படுவீர்கள் என்று சொல்லி,', 'Acts 16:31', 'அப்போஸ்தலர் 16:31', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 77),
  ('b1000000-0000-4000-8000-000000000079', 'For I am not ashamed of the Good News of Christ, because it is the power of God for salvation for everyone who believes, for the Jew first, and also for the Greek.', 'கிறிஸ்துவின் சுவிசேஷத்தைக்குறித்து நான் வெட்கப்படேன்; முன்பு யூதரிலும் பின்பு கிரேக்கரிலும் விசுவாசிக்கிறவனெவனோ அவனுக்கு இரட்சிப்பு உண்டாவதற்கு அது தேவபெலனாயிருக்கிறது.', 'Romans 1:16', 'ரோமர் 1:16', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 78),
  ('b1000000-0000-4000-8000-000000000080', 'for all have sinned, and fall short of the glory of God;', 'எல்லாரும் பாவஞ்செய்து, தேவமகிமையற்றவர்களாகி,', 'Romans 3:23', 'ரோமர் 3:23', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 79),
  ('b1000000-0000-4000-8000-000000000081', 'But God commends his own love toward us, in that while we were yet sinners, Christ died for us.', 'நாம் பாவிகளாயிருக்கையில் கிறிஸ்து நமக்காக மரித்ததினாலே, தேவன் நம்மேல் வைத்த தமது அன்பை விளங்கப்பண்ணுகிறார்.', 'Romans 5:8', 'ரோமர் 5:8', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 80),
  ('b1000000-0000-4000-8000-000000000082', 'There is therefore now no condemnation to those who are in Christ Jesus, who don’t walk according to the flesh, but according to the Spirit.', 'ஆனபடியால், கிறிஸ்து இயேசுவுக்குட்பட்டவர்களாயிருந்து, மாம்சத்தின்படி நடவாமல் ஆவியின்படியே நடக்கிறவர்களுக்கு ஆக்கினைத்தீர்ப்பில்லை.', 'Romans 8:1', 'ரோமர் 8:1', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 81),
  ('b1000000-0000-4000-8000-000000000083', 'We know that all things work together for good for those who love God, for those who are called according to his purpose.', 'அன்றியும், அவருடைய தீர்மானத்தின்படி அழைக்கப்பட்டவர்களாய்த் தேவனிடத்தில் அன்புகூருகிறவர்களுக்குச் சகலமும் நன்மைக்கு ஏதுவாக நடக்கிறதென்று அறிந்திருக்கிறோம்.', 'Romans 8:28', 'ரோமர் 8:28', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 82),
  ('b1000000-0000-4000-8000-000000000084', 'What then shall we say about these things? If God is for us, who can be against us?', 'இவைகளைக்குறித்து நாம் என்ன சொல்லுவோம்? தேவன் நம்முடைய பட்சத்திலிருந்தால் நமக்கு விரோதமாயிருப்பவன் யார்?', 'Romans 8:31', 'ரோமர் 8:31', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 83),
  ('b1000000-0000-4000-8000-000000000085', 'that if you will confess with your mouth that Jesus is Lord and believe in your heart that God raised him from the dead, you will be saved.', 'என்னவென்றால், கர்த்தராகிய இயேசுவை நீ உன் வாயினாலே அறிக்கையிட்டு, தேவன் அவரை மரித்தோரிலிருந்து எழுப்பினாரென்று உன் இருதயத்திலே விசுவாசித்தால் இரட்சிக்கப்படுவாய்.', 'Romans 10:9', 'ரோமர் 10:9', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 84),
  ('b1000000-0000-4000-8000-000000000086', 'Don’t be conformed to this world, but be transformed by the renewing of your mind, so that you may prove what is the good, well-pleasing, and perfect will of God.', 'நீங்கள் இந்தப் பிரபஞ்சத்திற்கு ஒத்த வேஷந்தரியாமல், தேவனுடைய நன்மையும் பிரியமும் பரிபூரணமுமான சித்தம் இன்னதென்று பகுத்தறியத்தக்கதாக, உங்கள் மனம் புதிதாகிறதினாலே மறுரூபமாகுங்கள்.', 'Romans 12:2', 'ரோமர் 12:2', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 85),
  ('b1000000-0000-4000-8000-000000000087', 'rejoicing in hope, enduring in troubles, continuing steadfastly in prayer,', 'நம்பிக்கையிலே சந்தோஷமாயிருங்கள்; உபத்திரவத்திலே பொறுமையாயிருங்கள்; ஜெபத்திலே உறுதியாய்த் தரித்திருங்கள்.', 'Romans 12:12', 'ரோமர் 12:12', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 86),
  ('b1000000-0000-4000-8000-000000000088', 'Now may the God of hope fill you with all joy and peace in believing, that you may abound in hope in the power of the Holy Spirit.', 'பரிசுத்த ஆவியின் பலத்தினாலே உங்களுக்கு நம்பிக்கை பெருகும்படிக்கு, நம்பிக்கையின் தேவன் விசுவாசத்தினால் உண்டாகும் எல்லாவித சந்தோஷத்தினாலும் சமாதானத்தினாலும் உங்களை நிரப்புவாராக.', 'Romans 15:13', 'ரோமர் 15:13', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 87),
  ('b1000000-0000-4000-8000-000000000089', 'No temptation has taken you except what is common to man. God is faithful, who will not allow you to be tempted above what you are able, but will with the temptation also make the way of escape, that you may be able to endure it.', 'மனுஷருக்கு நேரிடுகிற சோதனையேயல்லாமல் வேறே சோதனை உங்களுக்கு நேரிடவில்லை. தேவன் உண்மையுள்ளவராயிருக்கிறார்; உங்கள் திராணிக்கு மேலாக நீங்கள் சோதிக்கப்படுகிறதற்கு அவர் இடங்கொடாமல், சோதனையைத் தாங்கத்தக்கதாக, சோதனையோடுகூட அதற்குத் தப்பிக்கொள்ளும்படியான போக்கையும் உண்டாக்குவார்.', '1 Corinthians 10:13', '1 கொரிந்தியர் 10:13', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 88),
  ('b1000000-0000-4000-8000-000000000090', 'But now faith, hope, and love remain—these three. The greatest of these is love.', 'இப்பொழுது விசுவாசம், நம்பிக்கை, அன்பு இம்மூன்றும் நிலைத்திருக்கிறது; இவைகளில் அன்பே பெரியது.', '1 Corinthians 13:13', '1 கொரிந்தியர் 13:13', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 89),
  ('b1000000-0000-4000-8000-000000000091', 'Therefore if anyone is in Christ, he is a new creation. The old things have passed away. Behold, all things have become new.', 'இப்படியிருக்க, ஒருவன் கிறிஸ்துவுக்குள்ளிருந்தால் புதுசிருஷ்டியாயிருக்கிறான்; பழையவைகள் ஒழிந்து போயின, எல்லாம் புதிதாயின.', '2 Corinthians 5:17', '2 கொரிந்தியர் 5:17', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 90),
  ('b1000000-0000-4000-8000-000000000092', 'I have been crucified with Christ, and it is no longer I who live, but Christ lives in me. That life which I now live in the flesh, I live by faith in the Son of God, who loved me and gave himself up for me.', 'கிறிஸ்துவுடனேகூடச் சிலுவையிலறையப்பட்டேன்; ஆயினும், பிழைத்திருக்கிறேன்; இனி நான் அல்ல, கிறிஸ்துவே எனக்குள் பிழைத்திருக்கிறார்; நான் இப்பொழுது மாம்சத்தில் பிழைத்திருக்கிறதோ, என்னில் அன்புகூர்ந்து எனக்காகத் தம்மைத்தாமே ஒப்புக்கொடுத்த தேவனுடைய குமாரனைப்பற்றும் விசுவாசத்தினாலே பிழைத்திருக்கிறேன்.', 'Galatians 2:20', 'கலாத்தியர் 2:20', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 91),
  ('b1000000-0000-4000-8000-000000000093', 'But the fruit of the Spirit is love, joy, peace, patience, kindness, goodness, faith,', 'ஆவியின் கனியோ, அன்பு, சந்தோஷம், சமாதானம், நீடியபொறுமை, தயவு, நற்குணம், விசுவாசம்,', 'Galatians 5:22', 'கலாத்தியர் 5:22', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 92),
  ('b1000000-0000-4000-8000-000000000094', 'for by grace you have been saved through faith, and that not of yourselves; it is the gift of God,', 'கிருபையினாலே விசுவாசத்தைக் கொண்டு இரட்சிக்கப்பட்டீர்கள்; இது உங்களால் உண்டானதல்ல, இது தேவனுடைய ஈவு;', 'Ephesians 2:8', 'எபேசியர் 2:8', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 93),
  ('b1000000-0000-4000-8000-000000000095', 'Now to him who is able to do exceedingly abundantly above all that we ask or think, according to the power that works in us,', 'நாம் வேண்டிக்கொள்ளுகிறதற்கும் நினைக்கிறதற்கும் மிகவும் அதிகமாய் நமக்குள்ளே கிரியைசெய்கிற வல்லமையின்படியே, நமக்குச் செய்ய வல்லவராகிய அவருக்கு,', 'Ephesians 3:20', 'எபேசியர் 3:20', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 94),
  ('b1000000-0000-4000-8000-000000000096', 'And be kind to one another, tender hearted, forgiving each other, just as God also in Christ forgave you.', 'ஒருவருக்கொருவர் தயவாயும் மனஉருக்கமாயும் இருந்து, கிறிஸ்துவுக்குள் தேவன் உங்களுக்கு மன்னித்ததுபோல, நீங்களும் ஒருவருக்கொருவர் மன்னியுங்கள்.', 'Ephesians 4:32', 'எபேசியர் 4:32', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 95),
  ('b1000000-0000-4000-8000-000000000097', 'Finally, be strong in the Lord and in the strength of his might.', 'கடைசியாக, என் சகோதரரே, கர்த்தரிலும் அவருடைய சத்துவத்தின் வல்லமையிலும் பலப்படுங்கள்.', 'Ephesians 6:10', 'எபேசியர் 6:10', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 96),
  ('b1000000-0000-4000-8000-000000000098', 'Rejoice in the Lord always! Again I will say, “Rejoice!”', 'கர்த்தருக்குள் எப்பொழுதும் சந்தோஷமாயிருங்கள்; சந்தோஷமாயிருங்கள் என்று மறுபடியும் சொல்லுகிறேன்.', 'Philippians 4:4', 'பிலிப்பியர் 4:4', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 97),
  ('b1000000-0000-4000-8000-000000000099', 'In nothing be anxious, but in everything, by prayer and petition with thanksgiving, let your requests be made known to God.', 'நீங்கள் ஒன்றுக்குங்கவலைப்படாமல், எல்லாவற்றையுங்குறித்து உங்கள் விண்ணப்பங்களை ஸ்தோத்திரத்தோடே கூடிய ஜெபத்தினாலும் வேண்டுதலினாலும் தேவனுக்குத் தெரியப்படுத்துங்கள்.', 'Philippians 4:6', 'பிலிப்பியர் 4:6', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 98),
  ('b1000000-0000-4000-8000-000000000100', 'I can do all things through Christ who strengthens me.', 'என்னைப் பெலப்படுத்துகிற கிறிஸ்துவினாலே எல்லாவற்றையுஞ்செய்ய எனக்குப் பெலனுண்டு.', 'Philippians 4:13', 'பிலிப்பியர் 4:13', 'World English Bible (WEB)', 'Tamil Bible 1957', null, true, 'published', 99)
)
insert into public.daily_bible_verses (
  id, verse_en, verse_ta, reference_en, reference_ta,
  translation_en, translation_ta, scheduled_date, active, status, display_order
)
select
  seed.id::uuid, seed.verse_en, seed.verse_ta, seed.reference_en, seed.reference_ta,
  seed.translation_en, seed.translation_ta, seed.scheduled_date::date,
  seed.active, seed.status::public.content_status, seed.display_order
from seed
where not exists (
  select 1
  from public.daily_bible_verses existing
  where lower(existing.reference_en) = lower(seed.reference_en)
);

commit;
